private void btnPrintA5_Click(object sender, EventArgs e)
{
    PrintReceiptFull("Report/Account/Receipt/PhieuThu_Full_A5.repx");
}

private void btnPrintA80_Click(object sender, EventArgs e)
{
    PrintReceiptFull("Report/Account/Receipt/PhieuThu_Full_A80.repx");
}

private void PrintReceiptFull(string strFileReport)
{
    #region Save receipt

    if (btnSave.Enabled)
    {
        if (!IsValidEditForm())
            return;

        if (!SaveData())
            return;

        lngReceiptIDSaved = lngReceiptID = itemReceiptEditing.ReceiptID;
        bolIsOk = true;
    }
    #endregion

    #region Print receipt

    if (itemReceiptEditing.ReceiptID != null)
    {

        bolIsOk = false; // khi in không cần load lại lưới lâu

        DataTable dtbPrint = itemReceiptEditing.GetDataTable("ACC_Receipt_PrintBill_Master", "@ReceiptID", itemReceiptEditing.ReceiptID);

        if (dtbPrint != null && dtbPrint.Rows.Count > 0)
        {

            dtbPrint.Columns.Add("Lien", typeof(string));
            DataRow drwP = dtbPrint.NewRow();
            for (int i = 0; i < dtbPrint.Columns.Count; i++)// tạo ra 2 master để in 2 liên cho A5.
            {
                drwP[i] = dtbPrint.Rows[0][i];
            }
            dtbPrint.Rows.Add(drwP);
            dtbPrint.Rows[0]["Lien"] = "Copy(liên) 1: Save(lưu)";
            dtbPrint.Rows[1]["Lien"] = "Copy(liên) 2: Guests keep(khách giữ)";

            SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbPrint, strFileReport, false);

            frm.SetParameter("pUser", Global.Variable.LoginFullname);
            frm.SetParameter("pPartnerName", uPartner.PartnerName);
            frm.SetParameter("pMoneyText", txtMoneyText.Text);
            frm.SetParameter("pTotalMoney", txtTotalMoney.Text);
            frm.Show();
        }
        else
            ErrorManager.Error("Việc in phiếu thu bị lỗi!");
    }

    #endregion

    #region Reset form

    if (chkAddMore.Checked)
    {
        lblCmdResult.Visible = true;
        ResetData();
        new Thread(HideCmdResult).Start();
    }

    #endregion
}

