  label38: { y: 596, h: 22, x: X, w: LW, font: '8F, System.Drawing.FontStyle.Bold', align: 'TopCenter', canGrow: true, multiline: true }
};

var names = Object.keys(layout);
for (var n = 0; n < names.length; n++) {
  var name = names[n];
  var cfg = layout[name];
  var blockRe = new RegExp('// \\r\\n            // ' + name + '\\r\\n            // \\r\\n[\\s\\S]*?(?=\\r\\n            // \\r\\n            // )', 'm');
  var m = c.match(blockRe);
  if (!m) {
    console.log('MISSING ' + name);
    continue;
  }
  var block = m[0];
  var x = cfg.x !== undefined ? cfg.x : X;
  var w = cfg.w !== undefined ? cfg.w : W;
  block = block.replace(new RegExp('this\\.' + name + '\\.LocationFloat = new DevExpress\\.Utils\\.PointFloat\\([^)]+\\);'), 'this.' + name + '.LocationFloat = new DevExpress.Utils.PointFloat(' + x + 'F, ' + cfg.y + 'F);');
  block = block.replace(new RegExp('this\\.' + name + '\\.SizeF = new System\\.Drawing\\.SizeF\\([^)]+\\);'), 'this.' + name + '.SizeF = new System.Drawing.SizeF(' + w + 'F, ' + cfg.h + 'F);');
  if (cfg.font) {
    block = block.replace(new RegExp('this\\.' + name + '\\.Font = new System\\.Drawing\\.Font\\([^)]+\\);'), 'this.' + name + '.Font = new System.Drawing.Font("Times New Roman", ' + cfg.font + ');');
  }
  if (cfg.align) {
    if (/TextAlignment =/.test(block)) {
      block = block.replace(new RegExp('this\\.' + name + '\\.TextAlignment = DevExpress\\.XtraPrinting\\.TextAlignment\\.[^;]+;'), 'this.' + name + '.TextAlignment = DevExpress.XtraPrinting.TextAlignment.' + cfg.align + ';');
    }
  }
  if (cfg.canGrow) {
    if (!/CanGrow = true/.test(block)) {
      block = block.replace(new RegExp('(this\\.' + name + '\\.Name = "[^"]+";)'), '$1\r\n            this.' + name + '.CanGrow = true;');
    }
  }
  if (cfg.multiline) {
    if (!/Multiline = true/.test(block)) {
      block = block.replace(new RegExp('(this\\.' + name + '\\.Name = "[^"]+";)'), '$1\r\n            this.' + name + '.Multiline = true;');
    }
  }
  if (cfg.fixReasonBinding) {
    block = block.replace(/this\.label24\.Text = "\[Table\.Reason\]";/, 'this.label24.DataBindings.AddRange(new DevExpress.XtraReports.UI.XRBinding[] {\r\n                        new DevExpress.XtraReports.UI.XRBinding("Text", null, "Table.Reason")});\r\n            this.label24.Text = "label24";');
  }
  c = c.replace(m[0], block);
}

fs.writeFileSync(dst, c, 'utf8');
console.log('Created ' + dst);

