{
    if (itemPaymentEditing.PaymentID != null)
    {
        bolIsOk = false; // khi in không cần load lại lưới lâu

        DataTable dtbPrint = itemPaymentEditing.GetDataTable("ACC_Payment_PrintBill", "@PaymentID", itemPaymentEditing.PaymentID);

        if (dtbPrint != null && dtbPrint.Rows.Count > 0)
        {
            dtbPrint.Columns.Add("Lien", typeof(string));
            DataRow drwP = dtbPrint.NewRow();
            for (int i = 0; i < dtbPrint.Columns.Count; i++)// tạo ra 2 master để in 2 liên cho A5.
            {
                drwP[i] = dtbPrint.Rows[0][i];
            }
            dtbPrint.Rows.Add(drwP);
            dtbPrint.Rows[0]["Lien"] = "Copy(liên) 1: Save(lưu)";
            dtbPrint.Rows[1]["Lien"] = "Copy(liên) 2: Guests keep(khách giữ)";

            SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbPrint, strFileReport, false);

            frm.SetParameter("pPartnerName", uPartner.PartnerName);
            frm.SetParameter("pMoneyText", txtMoneyText.Text);
            frm.SetParameter("pTotalMoney", txtTotalMoney.Text);
            frm.Show();
        }
    }
}

