private void PrintPaymentWithSave(string strFileReport)
{
    #region Save payment

    if (btnSave.Enabled)
    {
        if (!IsValidEditForm())
            return;

        if (!SaveData())
            return;

        lngPaymentIDSaved = itemPaymentEditing.PaymentID; // nhớ mã mới thêm
        bolIsOk = true;
    }
    #endregion

    PrintPaymentFull(strFileReport);

    if (chkAddMore.Checked)
    {
        lblCmdResult.Visible = true;
        ResetData();
        mnuItemRefresh_Click(null, null);
        new Thread(HideCmdResult).Start();
    }
}

